package glitch

import data.glitch_lib

# Helper functions for pattern matching
check_auth_disable(value) {
    value.ir_type == "Boolean"
    value.value == false
} else {
    value.ir_type == "String"
    lower := lower(value.value)
    lower == "false" || lower == "no" || lower == "none" || lower == "disabled"
} else {
    value.ir_type == "String"
    regex.match("(?i)^(none|null|anonymous|public|anyone|\\*)$", value.value)
}

check_auth_enable(value) {
    value.ir_type == "Boolean"
    value.value == true
} else {
    value.ir_type == "String"
    lower := lower(value.value)
    lower == "true" || lower == "yes" || lower == "enabled"
}

check_wildcard_permission(value) {
    value.ir_type == "String"
    regex.match("(?i)^(\\*|all|any|admin|owner|root|superuser)$", value.value)
} else {
    value.ir_type == "Array"
    wildcard_in_array(value.value)
}

wildcard_in_array(array) {
    element := array[_]
    element.ir_type == "String"
    regex.match("(?i)^(\\*|all|any|admin|owner|root|superuser)$", element.value)
}

check_broad_network(value) {
    value.ir_type == "String"
    regex.match("(?i)^(0\\.0\\.0\\.0/0|::/0|\\*|any|all)$", value.value)
} else {
    value.ir_type == "Array"
    broad_cidr_in_array(value.value)
} else {
    value.ir_type == "Hash"
    broad_cidr_in_hash(value.value)
}

broad_cidr_in_array(array) {
    element := array[_]
    element.ir_type == "String"
    regex.match("(?i)^(0\\.0\\.0\\.0/0|::/0|\\*|any|all)$", element.value)
}

broad_cidr_in_hash(hash) {
    [_, value] := hash[key]
    check_broad_network(value)
}

check_overly_permissive(value) {
    value.ir_type == "String"
    regex.match("(?i)^(\\*|all|any|0\\.0\\.0\\.0/0|::/0)$", value.value)
} else {
    value.ir_type == "Integer"
    check_port_range(value.value)
}

check_port_range(port) {
    port == 0
} else {
    port >= 1024
} else {
    port == 65535
}

check_protocol_any(value) {
    value.ir_type == "String"
    lower := lower(value.value)
    lower == "any" || lower == "all" || lower == "-1"
}

# Pattern 1: Missing or Disabled Authentication/Authorization
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    check_auth_field(attr.name)
    check_auth_disable(attr.value)

    result := {
        "type": "sec_invalid_bind",
        "element": attr,
        "path": parent.path,
        "description": "Authentication or authorization is missing or disabled (CWE-284, CWE-862, CWE-306)"
    }
}

check_auth_field(name) {
    regex.match("(?i)(auth|permission|access|principal|identity)", name)
}

# Pattern 2: Public/Anonymous Access Enabled
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
