        "description": "Public or anonymous access is enabled (CWE-284, CWE-862)"
    }
}

check_public_field(name) {
    regex.match("(?i)(public|anonymous|external|open)", name)
}

# Pattern 3: Overly Permissive Policies/Wildcard Usage
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]
