        "type": "sec_invalid_bind",
        "element": attr,
        "path": parent.path,
        "description": "Overly permissive policy with wildcard usage (CWE-284, CWE-863, CWE-732)"
    }
}

check_permission_field(name) {
    regex.match("(?i)(action|privilege|permission|role|scope|policy)", name)
}

# Pattern 4: Overly Broad Network Rules
Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
